[Form]
public class NDXXLSImportHV extends FormRun
{
    #define.Raumungsartikel("RA")
    PriceDiscAdmTable           priceDiscAdmTable;
    boolean                     lDoRedraw;
    Int64                       timeStart;

    NDXExcelFileType            nDX_ExcelFileType;
    CustVendItemGroupId         custVendItemGroupId;

    PriceDiscAdmTrans           priceDiscAdmTransJournal;
    boolean                     lOnlyPriceDiff;                 // nur Preisunterschiede übertragen
    boolean                     lPurgeJournal;                  // Journal bereinigen
    QueryBuildRange             qbrImportHeader;
}

/// <summary>
/// DebuC 03.12.24
/// </summary>
public void init()
{
    if (element.args())
    {
        switch (element.args().dataset())
        {
            case tablenum(PriceDiscAdmTrans)    :
                priceDiscAdmTransJournal = element.args().record();
                priceDiscAdmTable        = PriceDiscAdmTable::find(priceDiscAdmTransJournal.JournalNum);
                break;
            case tablenum(priceDiscAdmTable)    :
                priceDiscAdmTable        = element.args().record();
        }
    }

    super();       

    lOnlyPriceDiff = true;
    lPurgeJournal  = true;
    cbTransOnlyPriceDiff.value(lOnlyPriceDiff);
    cbDeleteJournalPosWithoutPriceDiff.value(lPurgeJournal);

    element.searchNDXSignature();
    element.activateTabPages();
}

/// <summary>
/// DebuC 06.01.25
/// </summary>
public void close()
{
    super();

    NDXExcelPriceImportHeader::deleteImportedRecords();
    FormDataSource fds = FormDataUtil::getFormDataSource(element.args().record());
    fds.executeQuery();
}

/// <summary>
///
/// </summary>
private void searchNDXSignature()
{
    NDXExcelPriceImportHeader priceImportHeader;

    priceImportHeader = NDXExcelPriceImportHeader::findLatest(curUserId(), priceDiscAdmTable.RecId);
    if(priceImportHeader)
    {
        FilterNDXSignature.text(priceImportHeader.Signature);
        NDXExcelPriceImportHeader_ds.executeQuery();
    }
}

/// <summary>
/// DebuC 04.03.25
/// </summary>
private void activateTabPages()
{
    if(FilterNDXSignature.valueStr())
    {
        tpImportedData.visible(true);
        tpNotImported.visible(true);
        tpPriceDiff.visible(true);
    }
    else
    {
        tpImportedData.visible(false);
        tpNotImported.visible(false);
        tpPriceDiff.visible(false);
    }
}

/// <summary>
/// DebuC 03.12.24
/// </summary>
public void init()
{
    super();

    qbrImportHeader = this.query().dataSourceTable(tableNum(NDXExcelPriceImportHeader)).addRange(fieldNum(NDXExcelPriceImportHeader, Signature));
    qbrImportHeader.value(queryValue(FilterNDXSignature.valueStr()));
}

/// <summary>
/// DebuC 03.12.24
/// </summary>
public void executeQuery()
{
    qbrImportHeader.value(queryValue(FilterNDXSignature.valueStr()));
    element.activateTabPages();
    super();           
}

/// <summary>
/// DebuC 03.12.24
/// </summary>
public void init()
{            
    QueryBuildDataSource    qbd;
    ;
    super();

