/// <summary>
/// DebuC 03.12.24
/// </summary>
public void init()
{            
    QueryBuildDataSource    qbd;
    ;
    super();

    qbd             = this.query().dataSourceTable(tablenum(NDXExcelPriceImport));
    qbd.addRange(fieldnum(NDXExcelPriceImport, IsImportable)).value(QueryValue(NoYes::No));
