/// <summary>
/// DebuC 03.12.24
/// </summary>
public void lookup()
{
    Query                   query = new Query();
    QueryBuildDataSource    qbds;
    SysTableLookup          sysTableLookup;

    sysTableLookup = SysTableLookup::newParameters(tableNum(NDXExcelPriceImportHeader), this);

    qbds = query.addDataSource(tableNum(NDXExcelPriceImportHeader));
    qbds.addRange(fieldnum(NDXExcelPriceImportHeader, CreatedBy)).value(queryvalue(curuserid()));
    qbds.addRange(fieldNum(NDXExcelPriceImportHeader, PriceDiscAdmTable)).value(queryvalue(PriceDiscAdmTable::find(priceDiscAdmTransJournal.JournalNum).RecId));
    sysTableLookup.addLookupfield(fieldNum(NDXExcelPriceImportHeader, Signature), true);
    sysTableLookup.addLookupfield(fieldNum(NDXExcelPriceImportHeader, PriceDiscAdmTable));
    sysTableLookup.addLookupfield(fieldNum(NDXExcelPriceImportHeader, NDXExcelTable));
    sysTableLookup.addLookupfield(fieldNum(NDXExcelPriceImportHeader, CreatedBy));
    sysTableLookup.addLookupfield(fieldNum(NDXExcelPriceImportHeader, CreatedDateTime));
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

/// <summary>
/// DebuC 03.12.24
/// </summary>
/// <returns>boolean</returns>
public boolean modified()
{
    boolean ret;

    ret = super();
    NDXExcelPriceImportHeader_ds.executeQuery();
    element.activateTabPages();
    return ret;
}

