/// <summary>
/// DebuC 03.12.24
/// </summary>
public void clicked()
{
    MenuFunction menuFunction;
    Args args = new Args();
    NDXExcelPriceJournalImportParameter parameter = new NDXExcelPriceJournalImportParameter();
    parameter.parmExcelFileId(NDXExcelTable.FileId);
    parameter.parmPriceDiscJournalNum(priceDiscAdmTransJournal.JournalNum);
    parameter.parmRelation(priceDiscAdmTransJournal.relation);
    parameter.parmItemCode(priceDiscAdmTransJournal.ItemCode);
    parameter.parmAccountCode(priceDiscAdmTransJournal.AccountCode);
    parameter.parmAccountRelation(priceDiscAdmTransJournal.AccountRelation);
    parameter.parmFromDate(priceDiscAdmTransJournal.FromDate);
    args.parmObject(parameter);

    super();

    menuFunction = new MenuFunction(menuItemActionStr(NDXExcelPriceJournalImportController), MenuItemType::Action);

    if(menuFunction && menuFunction.checkAccessRights())
    {
        delete_from NDXExcelPriceImportHeader
            where NDXExcelPriceImportHeader.CreatedBy == curUserId()
            && NDXExcelPriceImportHeader.PriceDiscAdmTable == priceDiscAdmTable.RecId;

        menuFunction.run(args);
        menuFunction.wait();

        element.searchNDXSignature();
    }
}

/// <summary>
/// DebuC 03.12.24
/// </summary>
public void clicked()
{
    PriceDiscAdmTrans       priceDiscAdmTrans;
    CurrencyCode            currency = Ledger::accountingCurrency(CompanyInfo::current());
    InventDimId             inventDimId = InventDim::findOrCreateBlank().inventDimId;
    PriceDiscAdmTable       lpriceDiscAdmTable;
    NDXExcelPriceImport     excelPriceImport
    ;
    this.enabled(false);
    super();

    select firstonly lpriceDiscAdmTable where lpriceDiscAdmTable.RecId == NDXExcelPriceImportHeader.PriceDiscAdmTable;

    priceDiscAdmTrans.selectForUpdate(true);
    while select forupdate excelPriceImport
        where       excelPriceImport.isImportable == NoYes::Yes
        &&          excelPriceImport.NDXExcelPriceImportHeader == NDXExcelPriceImportHeader.RecId
    {

        // Nur Positonen übertragen, bei denen sich der Preis geändert hat
        if (lOnlyPriceDiff && excelPriceImport.PriceDiff == NoYes::No)
        {
            continue;
        }
        // besteht der Journaleintrag bereits?
        select firstonly priceDiscAdmTrans
            where       priceDiscAdmTrans.JournalNum    == lpriceDiscAdmTable.JournalNum
            &&      priceDiscAdmTrans.ItemCode          == NDXExcelPriceImportHeader.ItemCode
            &&      priceDiscAdmTrans.AccountCode       == NDXExcelPriceImportHeader.AccountCode
            &&      priceDiscAdmTrans.AccountRelation   == NDXExcelPriceImportHeader.AccountRelation
            &&      priceDiscAdmTrans.ItemRelation      == excelPriceImport.ItemRelation
            &&      priceDiscAdmTrans.InventDimId       == inventDimId
            &&      priceDiscAdmTrans.relation          == NDXExcelPriceImportHeader.Relation;

        ttsbegin;

        if (!priceDiscAdmTrans)
        {                    
            priceDiscAdmTrans.initValue();                    

            priceDiscAdmTrans.JournalNum        = lpriceDiscAdmTable.JournalNum;
            priceDiscAdmTrans.ItemCode          = NDXExcelPriceImportHeader.ItemCode;
            priceDiscAdmTrans.AccountCode       = NDXExcelPriceImportHeader.AccountCode;
            priceDiscAdmTrans.AccountRelation   = NDXExcelPriceImportHeader.AccountRelation;
            priceDiscAdmTrans.ItemRelation      = excelPriceImport.ItemRelation;
            priceDiscAdmTrans.relation          = NDXExcelPriceImportHeader.Relation;

            if (excelPriceImport.CurrencyCode)
            {
                priceDiscAdmTrans.Currency      = excelPriceImport.CurrencyCode;
            }
            else            
            {
                priceDiscAdmTrans.Currency      = currency;
            }
            priceDiscAdmTrans.InventDimId       = inventDimId;

            priceDiscAdmTrans.initFromItemCode();
            if (excelPriceImport.PriceUnit)
            {
                priceDiscAdmTrans.PriceUnit = excelPriceImport.PriceUnit;
            }

            // SearchAgain initialisieren
            priceDiscAdmTrans.modifiedField(fieldnum(PriceDiscAdmTrans, relation));                    
        }

        priceDiscAdmTrans.Amount    = NDX_PriceInfo::CurrencyDecRound(excelPriceImport.Amount);
        priceDiscAdmTrans.FromDate  = NDXExcelPriceImportHeader.FromDate;

        priceDiscAdmTrans.write();
        excelPriceImport.isImported = NoYes::Yes;
        excelPriceImport.update();

        ttscommit;
    }
    NDXExcelPriceImportHeader.selectForUpdate(true);
    ttsbegin;
    NDXExcelPriceImportHeader.isImportedToJournal = NoYes::Yes;
    NDXExcelPriceImportHeader.update();
    ttscommit;
    NDXExcelPriceImportHeader_ds.executeQuery();

    if (lPurgeJournal)
    {
        // Positionen aus Journal löschen, bei denen sich der Preis nicht geändert hat
        ttsbegin;
        while select forUpdate priceDiscAdmTrans
            where       priceDiscAdmTrans.JournalNum        == priceDiscAdmTable.JournalNum
        {
            if (priceDiscAdmTrans.PriceDiscTableRef
                && priceDiscAdmTrans.KCS_AmountOld == priceDiscAdmTrans.Amount)
            {
                priceDiscAdmTrans.delete();
            }
        }
        ttscommit;
    }

    this.enabled(true);
}

